using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.Xml;
using UnityEngine;
using UnityEngine.UI;

namespace Pwaat.Accessibility.Ui
{
    // One bounded post-commit snapshot combines feedback generated by the same native presentation.
    // It does not schedule speech by duration, stop the backend, or run without an event request.
    internal sealed class StoryPresentationHandler : IDisposable
    {
        private readonly UiRuntime _runtime;
        private readonly MonoBehaviour _host;
        private readonly ControlGlyphs _glyphs;
        private readonly Dictionary<string, string> _images = new Dictionary<string, string>(StringComparer.Ordinal);
        private readonly HashSet<keyGuideBase> _guides = new HashSet<keyGuideBase>();
        private readonly Dictionary<keyGuideBase, string> _guideLast = new Dictionary<keyGuideBase, string>();
        private readonly List<string> _story = new List<string>();
        private readonly Dictionary<Component, string> _uiTails = new Dictionary<Component, string>();
        private readonly Dictionary<Component, string> _ui = new Dictionary<Component, string>();
        private readonly Dictionary<Component, Action> _uiReads = new Dictionary<Component, Action>();
        private bool _flushing;
        private picePlateCtrl _evidence;
        private bool _evidenceSpoken;
        private bool _evidenceReady;
        private int _evidenceId = -1;
        private bool _requested;
        private bool _disposed;
        private bool _introPending = true;
        private bool _healthRequested;
        private bool _healthShown;
        private decimal? _lastHealth;
        private int _damageDepth;
        private decimal _beforeDamage;
        private string _damageText;
        private judgmentCtrl _judgment;
        private int _judgmentType;
        private int _judgmentPulse;
        internal StoryPresentationHandler(UiRuntime runtime, MonoBehaviour host)
        {
            _runtime = runtime; _host = host; _glyphs = new ControlGlyphs(runtime.Messages);
            foreach (XmlElement row in UiResources.EmbeddedXml("Pwaat.Accessibility.StoryImageText.xml").SelectNodes("/images/image"))
            { _images.Add(row.GetAttribute("path") + row.GetAttribute("bundle") + ":" + row.GetAttribute("sprite"), row.InnerText); }
        }
        internal bool Foreground()
        {
            return (_runtime.Assistance == null || !_runtime.Assistance.IsOpen) && advCtrl.instance != null && advCtrl.instance.active && advCtrl.instance.body != null && advCtrl.instance.body.activeInHierarchy && NativeFields.Visible(advCtrl.instance)
                && (optionCtrl.instance == null || !optionCtrl.instance.is_open)
                && (SaveLoadUICtrl.instance == null || !SaveLoadUICtrl.instance.is_open)
                && (_runtime.StoryUi == null || !_runtime.StoryUi.BoxBlocks());
        }
        private bool IsPsycheStatusPage()
        {
            recordListCtrl list = recordListCtrl.instance;
            GlobalWork g = GSStatic.global_work_;
            return list != null && list.is_open && list.body_active
                && (_runtime.Assistance == null || !_runtime.Assistance.BlocksInput)
                && (optionCtrl.instance == null || !optionCtrl.instance.is_open)
                && (SaveLoadUICtrl.instance == null || !SaveLoadUICtrl.instance.is_open)
                && (_runtime.StoryUi == null || !_runtime.StoryUi.BoxBlocks())
                && g != null && g.r.no_0 == 8
                && _runtime.PsycheLocks != null && _runtime.PsycheLocks.IsStatusChallenge();
        }
        internal bool CanAcceptHealthQuery()
        {
            return Foreground() || IsPsycheStatusPage();
        }
        internal void TraceHealthRequest()
        {
            recordListCtrl list = recordListCtrl.instance;
            GlobalWork g = GSStatic.global_work_;
            _runtime.Trace("health_hotkey", "foreground=" + Foreground()
                + " statusPage=" + IsPsycheStatusPage()
                + " recordOpen=" + (list != null && list.is_open)
                + " recordBody=" + (list != null && list.body_active)
                + " detail=" + (list != null && list.detail_open)
                + " routine=" + g.r.no_0 + ":" + g.r.no_1 + ":" + g.r.no_2
                + " return=" + g.r_bk.no_0 + ":" + g.r_bk.no_1 + ":" + g.r_bk.no_2
                + " menu=" + g.psy_menu_active_flag
                + " page=" + (GSStatic.status_work_ == null ? "unavailable" : GSStatic.status_work_.page_status.ToString(CultureInfo.InvariantCulture))
                + " gaugeBody=" + (lifeGaugeCtrl.instance != null && lifeGaugeCtrl.instance.body_active)
                + " gaugeActive=" + (lifeGaugeCtrl.instance != null && lifeGaugeCtrl.instance.gauge_active)
                + " gaugePosition=" + (lifeGaugeCtrl.instance != null && (bool)NativeFields.Get(lifeGaugeCtrl.instance, "to_active_pos_")));
        }
        private void Request()
        {
            if (_requested || _disposed || _flushing) { return; }
            _requested = true; _host.StartCoroutine(AfterCommit());
        }
        private IEnumerator AfterCommit()
        {
            yield return null;
            _requested = false;
            if (_disposed) { yield break; }
            _flushing = true;
            try { Flush(); }
            catch (Exception error) { _runtime.ReadFailure("story-presentation", error); }
            finally { _flushing = false; }
        }
        internal void Story(string text) { if (!string.IsNullOrEmpty(text)) { _story.Add(text); Request(); } }
        internal void ReadUi(Component owner, Action read) { if (owner != null) { _uiReads[owner] = read; Request(); } }
        internal void Ui(Component owner, string text, string tail = null) { if (owner != null) { _ui[owner] = text; if (!string.IsNullOrEmpty(tail)) { _uiTails[owner] = tail; } else { _uiTails.Remove(owner); } Request(); } }
        internal void ClearUi(Component owner) { if (!ReferenceEquals(owner, null)) { _ui.Remove(owner); _uiTails.Remove(owner); _uiReads.Remove(owner); } }
        internal void EvidenceEntry(picePlateCtrl owner, int id)
        {
            _evidence = null; _evidenceId = -1; _evidenceSpoken = false; _evidenceReady = false;
            if (owner == null || piceDataCtrl.instance == null || id < 0 || id >= piceDataCtrl.instance.note_data.Count) { return; }
            _evidence = owner; _evidenceId = id;
        }
        internal void EvidenceReady(picePlateCtrl owner, bool completed = false) { if (_evidence == owner && !_evidenceSpoken) { _evidenceReady |= completed; Request(); } }
        internal void EvidenceHidden(picePlateCtrl owner) { if (_evidence == owner) { _evidence = null; _evidenceSpoken = false; _evidenceId = -1; } }
        internal string EvidenceText()
        {
            picePlateCtrl owner = _evidence;
            if (owner == null || !owner.body_active || !owner.is_play || !NativeFields.Visible(owner)) { return null; }
            return RecordText(NativeFields.TextValue(owner.icon_name), NativeFields.Texts(owner.comment.line_));
        }
        internal string RecordText(string name, string description)
        {
            return NativeFields.Join(string.IsNullOrEmpty(description) ? name : string.Format(_runtime.Messages.Get("story.evidence-name"), name), description);
        }
        private bool IsStoryGuide(keyGuideBase guide)
        {
            if (guide == null) { return false; }
            return (messageBoardCtrl.instance != null && guide == messageBoardCtrl.instance.guide_ctrl)
                || (recordListCtrl.instance != null && guide == recordListCtrl.instance.record_guide)
                || guide == keyGuideCtrl.instance;
        }
        internal void Guide(keyGuideBase guide) { if (IsStoryGuide(guide)) { _guides.Add(guide); Request(); } }
        internal void GuideClosed(keyGuideBase guide) { _guides.Remove(guide); _guideLast.Remove(guide); if (_runtime.Assistance != null) { _runtime.Assistance.GuideHidden(guide); } }
        private string ReadGuide(keyGuideBase guide)
        {
            recordListCtrl record = recordListCtrl.instance;
            bool recordPage = record != null && guide == record.record_guide && record.is_open && record.body_active && !record.detail_open && !record.is_page_changing
                && (_runtime.Assistance == null || !_runtime.Assistance.BlocksInput)
                && (optionCtrl.instance == null || !optionCtrl.instance.is_open)
                && (SaveLoadUICtrl.instance == null || !SaveLoadUICtrl.instance.is_open)
                && (_runtime.StoryUi == null || !_runtime.StoryUi.BoxBlocks());
            bool luminol = _runtime.Luminol != null && _runtime.Luminol.CanRead() && guide == keyGuideCtrl.instance;
            if ((!Foreground() && !recordPage && !luminol) || !IsStoryGuide(guide) || !NativeFields.Visible(guide)) { return null; }
            GameObject body = NativeFields.Get(guide, "body_") as GameObject;
            if (body != null && (!body.activeInHierarchy || body.transform.localScale.y <= 0f)) { return null; }
            guideCtrl normal = guide as guideCtrl;
            if (normal != null && (!normal.getEnables() || normal.current_guide == guideCtrl.GuideType.NO_GUIDE)) { return null; }
            if (normal != null && normal.is_open_close_guid()) { return null; }
            keyGuideBoard board = guide as keyGuideBoard;
            if (board != null && (!board.active || board.current_guide == keyGuideBase.Type.NO_GUIDE || board.CheckOpen() || board.CheckClose())) { return null; }
            if (messageBoardCtrl.instance != null && guide == messageBoardCtrl.instance.guide_ctrl && recordListCtrl.instance != null && recordListCtrl.instance.is_open) { return null; }
            if (guide is recordGuideCtrl && (recordListCtrl.instance == null || !recordListCtrl.instance.is_open || !recordListCtrl.instance.body_active)) { return null; }
            return _runtime.Batch.ReadGuideText(guide);
        }
        internal void HealthEvent() { _healthRequested = true; Request(); }
        internal bool HealthVisible()
        {
            lifeGaugeCtrl g = lifeGaugeCtrl.instance;
            return CanAcceptHealthQuery() && g != null && NativeFields.Visible(g) && g.body_active && g.gauge_active
                && (bool)NativeFields.Get(g, "to_active_pos_");
        }
        internal decimal RenderedHealth()
        {
            if (lifeGaugeCtrl.instance == null) { throw new InvalidOperationException("No native gauge."); }
            IList blue = (IList)NativeFields.Get(lifeGaugeCtrl.instance, "gauge_blue_");
            int count = 0; bool shortBar = false;
            foreach (AssetBundleSprite bar in blue)
            {
                if (bar == null || !bar.active || !bar.enabled || bar.obj == null || !bar.obj.activeInHierarchy) { continue; }
                count++;
                Sprite sprite = bar.sprite_renderer_ != null ? bar.sprite_renderer_.sprite : null;
                if (sprite != null && sprite.name == "gauge_8") { shortBar = true; }
            }
            return HealthUnits(count, GSStatic.global_work_.title == TitleId.GS1, shortBar);
        }
        internal static decimal HealthUnits(int renderedSegments, bool gs1, bool shortBar)
        {
            if (renderedSegments < 0 || renderedSegments > 10) { throw new ArgumentOutOfRangeException("renderedSegments"); }
            if (shortBar && renderedSegments == 1) { return 1m; }
            return gs1 ? renderedSegments / 2m : renderedSegments;
        }
        private string HealthText(decimal cells)
        { return string.Format(_runtime.Messages.Get("story.health"), cells.ToString("0.#", CultureInfo.InvariantCulture)); }
        internal void QueryHealth()
        {
            string text = _runtime.Messages.Get("story.no-health");
            if (HealthVisible())
            {
                text = HealthText(RenderedHealth());
            }
            else { _runtime.Trace("health_query", "stage=hidden"); }
            // The native gauge and lock display are independent. A hidden gauge must not suppress an already revealed challenge count.
            if (_runtime.PsycheLocks != null) text = NativeFields.Join(text, _runtime.PsycheLocks.RemainingText(true));
            _runtime.Speech.Say(text, true);
        }
        internal void BeginDamage()
        {
            if (_damageDepth++ == 0) { _beforeDamage = lifeGaugeCtrl.instance == null ? 0m : RenderedHealth(); }
        }
        internal void EndDamage() { if (_damageDepth > 0) { _damageDepth--; } HealthEvent(); }
        internal void HealthUpdated()
        {
            if (_damageDepth > 0)
            {
                decimal after = RenderedHealth(); decimal lost = _beforeDamage - after;
                if (lost > 0m)
                { _damageText = string.Format(_runtime.Messages.Get("story.damage"), lost.ToString("0.#", CultureInfo.InvariantCulture)); _beforeDamage = after; }
            }
            HealthEvent();
        }
        internal void HealthHidden() { _healthShown = false; _lastHealth = null; }
        private void Flush()
        {
            if (_runtime.Assistance != null && _runtime.Assistance.IsOpen) { _story.Clear(); _uiTails.Clear(); _ui.Clear(); _guides.Clear(); _uiReads.Clear(); return; }
            List<Action> reads = new List<Action>(_uiReads.Values); _uiReads.Clear();
            foreach (Action read in reads) { read(); }
            List<string> output = new List<string>();
            bool foreground = Foreground();
            if (foreground)
            {
                string evidence = EvidenceText();
                if (!_evidenceSpoken && !string.IsNullOrEmpty(evidence) && (_story.Count > 0 || _evidenceReady))
                { output.Add(evidence); _evidenceSpoken = true; _runtime.Trace("story_evidence", "id=" + _evidenceId); }
                output.AddRange(_story);
            }
            _story.Clear();
            foreach (KeyValuePair<Component, string> entry in _ui)
            { if (entry.Key != null && NativeFields.Visible(entry.Key)) { output.Add(entry.Value); } }
            _ui.Clear();
            bool damaged = !string.IsNullOrEmpty(_damageText);
            if (damaged && foreground) { output.Add(_damageText); }
            _damageText = null;
            if (_healthRequested)
            {
                _healthRequested = false;
                if (HealthVisible())
                {
                    decimal cells = RenderedHealth();
                    if (!damaged && (!_healthShown || _lastHealth != cells)) { output.Add(HealthText(cells)); }
                    _healthShown = true; _lastHealth = cells;
                }
            }
            foreach (keyGuideBase guide in _guides)
            {
                string text;
                try { text = ReadGuide(guide); } catch (Exception error) { _runtime.ReadFailure("story-guide/" + guide.GetType().Name, error); continue; }
                if (!string.IsNullOrEmpty(text))
                { string announced = _runtime.Assistance == null ? text : _runtime.Assistance.AutomaticGuide(guide, text); if (!string.IsNullOrEmpty(announced)) { output.Add(announced); } _guideLast[guide] = text; }
            }
            _guides.Clear();
            if (foreground && _introPending && output.Count > 0) { if (_runtime.Speech.Preferences.Guides != GuideAnnouncement.Off) { output.Add(_runtime.Messages.Get("story.hotkeys")); } _introPending = false; }
            foreach (KeyValuePair<Component, string> entry in _uiTails)
            { if (entry.Key != null && NativeFields.Visible(entry.Key)) { output.Add(entry.Value); } }
            _uiTails.Clear();
            string speech = NativeFields.Join(output.ToArray());
            if (!string.IsNullOrEmpty(speech)) { _runtime.Speech.Say(speech, true); }
        }
        internal string Image(Sprite sprite, string folder, string bundle)
        {
            string value; string key = folder + ReplaceLanguage.GetFileName(folder, bundle) + ":" + (sprite == null ? "<null>" : sprite.name);
            if (!_images.TryGetValue(key, out value)) { throw new InvalidOperationException("Unaudited story image: " + key); }
            return value;
        }
        internal void BalloonVisible(objMoveCtrl owner)
        {
            if (!Foreground() || owner == null || !owner.is_play) { return; }
            AssetBundleSprite[] images = (AssetBundleSprite[])NativeFields.Get(owner, "obj_");
            AssetBundleSprite image = images[0];
            if (!image.active || !image.obj.activeInHierarchy) { return; }
            Sprite sprite = image.sprite_renderer_ != null ? image.sprite_renderer_.sprite : image.image_.sprite;
            _runtime.Speech.Say(Image(sprite, image.path_, image.name_), false);
        }
        internal void JudgmentStarting(judgmentCtrl owner, int type)
        { _judgment = owner; _judgmentType = type; _judgmentPulse = 0; }
        internal void JudgmentImpact(judgmentCtrl owner)
        {
            if (_judgment != owner || owner == null || !owner.body_active || !owner.result_active || !Foreground()) { return; }
            int pulse = _judgmentPulse++;
            IList sprites = (IList)NativeFields.Get(owner, "sprite_list_");
            int notCount = NativeFields.Number(owner, "not_count_");
            int guiltyCount = NativeFields.Number(owner, "guilty_count_");
            bool cjk = GSUtility.GetLanguageLayoutType(GSStatic.global_work_.language) == Language.JAPAN;
            int start = 0, count = 0;
            if (cjk) { start = pulse; count = pulse < 2 ? 1 : 0; }
            else if (_judgmentType == 0 && GSStatic.global_work_.language != Language.Pt_BR)
            { start = pulse == 0 ? 0 : notCount; count = pulse == 0 ? notCount : (pulse == 1 ? guiltyCount : 0); }
            else if (pulse == 0) { count = GSStatic.global_work_.language == Language.Pt_BR ? (_judgmentType == 0 ? notCount : 7) : notCount + guiltyCount; }
            if (count == 0) { return; }
            string bundle = "etc014" + GSUtility.GetResourceNameLanguage(GSStatic.global_work_.language);
            List<string> chars = new List<string>();
            for (int i = start; i < start + count && i < sprites.Count; i++)
            {
                AssetBundleSprite image = (AssetBundleSprite)sprites[i];
                if (!image.active || !image.obj.activeInHierarchy || image.sprite_renderer_.sprite == null) { return; }
                chars.Add(Image(image.sprite_renderer_.sprite, "/GS1/etc/", bundle));
            }
            _runtime.Speech.Say(string.Join("", chars.ToArray()), false);
        }
        internal void JudgmentEnded(judgmentCtrl owner) { if (_judgment == owner) { _judgment = null; } }
        internal void Clear()
        {
            _story.Clear(); _uiTails.Clear(); _ui.Clear(); _uiReads.Clear(); _guides.Clear(); _guideLast.Clear(); _evidence = null; _evidenceId = -1;
            _healthRequested = false; _healthShown = false; _lastHealth = null; _damageText = null; _damageDepth = 0; _judgment = null;
        }
        /// <summary>Invalidates unsubmitted feedback only.</summary>
        public void Dispose() { _disposed = true; Clear(); }
    }
}
